window.openModal=i=>{window.AudioEngine.play('click');document.getElementById(i).classList.remove('hidden');};

window.switchView=v=>{
    window.AudioEngine.play('click');
    document.querySelectorAll('.view').forEach(x=>x.classList.add('hidden'));
    const t=document.getElementById(`view-${v}`);
    if(t)t.classList.remove('hidden');
    document.getElementById('drawer').classList.add('translate-x-full');
    document.querySelectorAll('.sidebar-link').forEach(l=>l.classList.remove('bg-violetApex/15','text-violetApex','border-r-4','border-violetApex'));
    const n=document.getElementById(`nav-${v}`);
    if(n)n.classList.add('bg-violetApex/15','text-violetApex','border-r-4','border-violetApex');
    window.uiState.currentView=v;
    if(v==='tables'&&window.searchTables)window.searchTables();
    if(v==='debts'&&window.renderDebtsList)window.renderDebtsList();
    if(v==='dashboard'&&window.updateDashboardStats)window.updateDashboardStats();
    if(v==='invoices'&&window.renderInvoices)window.renderInvoices();
    if(v==='menu'&&window.renderMenuManagement)window.renderMenuManagement();
};

